package com.supportsphere.controller;
import com.supportsphere.model.*; import com.supportsphere.service.*; import com.supportsphere.util.*; import javafx.fxml.*; import javafx.scene.control.*; import javafx.scene.layout.*; import java.sql.Time; import java.time.*; import java.util.*;
public class RegisterController { @FXML TextField name,email,phone,area,city,landmark; @FXML PasswordField password; @FXML ComboBox<String> role; @FXML TextArea notes; @FXML VBox volunteerBox; @FXML TextField experience; @FXML TextField startTime,endTime; @FXML CheckBox grocery,medicine,transport,bill,appointment,document,household,other; private final AuthService auth=new AuthService(); @FXML void initialize(){role.getItems().setAll("I need assistance","I want to volunteer");role.getSelectionModel().selectFirst();toggle();role.setOnAction(e->toggle());} private void toggle(){volunteerBox.setVisible(role.getValue()!=null&&role.getValue().startsWith("I want"));volunteerBox.setManaged(volunteerBox.isVisible());} @FXML void create(){try{boolean v=role.getValue().startsWith("I want");List<String>s=new ArrayList<>();if(grocery.isSelected())s.add("Grocery Shopping");if(medicine.isSelected())s.add("Medicine Collection");if(transport.isSelected())s.add("Transportation");if(bill.isSelected())s.add("Bill Payment");if(appointment.isSelected())s.add("Appointment Assistance");if(document.isSelected())s.add("Document Assistance");if(household.isSelected())s.add("Household Assistance");if(other.isSelected())s.add("Other");int exp=v?Integer.parseInt(experience.getText().isBlank()?"0":experience.getText()):0;Time st=v?Time.valueOf(LocalTime.parse(startTime.getText())):Time.valueOf("09:00:00");Time en=v?Time.valueOf(LocalTime.parse(endTime.getText())):Time.valueOf("18:00:00");int id=auth.register(name.getText(),email.getText(),password.getText(),phone.getText(),v?Role.VOLUNTEER:Role.REQUESTER,area.getText(),city.getText(),landmark.getText(),notes.getText(),exp,st,en,s);Dialogs.info("Welcome to SupportSphere","Your account was created successfully. Please sign in to continue.");SceneManager.show("login.fxml","SupportSphere — Sign in");}catch(NumberFormatException e){Dialogs.error("Invalid experience","Experience must be a whole number.");}catch(Exception e){Dialogs.error("Could not create account",e.getMessage());}} @FXML void back(){try{SceneManager.show("login.fxml","SupportSphere — Sign in");}catch(Exception e){Dialogs.error("Navigation error",e.getMessage());}} }
